sys_script_include.script:
var WardUtilsClient = Class.create();
WardUtilsClient.prototype = Object.extendsObject(AbstractAjaxProcessor, {
    getWardDetails: function () {
        var ward = new GlideRecord('u_ward');
        if (ward.get(this.getParameter('sysparm_ward_id'))) {
            return JSON.stringify({
                ward_name: ward.getValue('u_ward_name'),
                department: ward.getValue('u_department'),
                floor: ward.getValue('u_floor')
            });
        }
        return JSON.stringify({error: "Ward not found"});
    }
});
